    ]));
    if !model.warnings.is_empty() || !model.failures.is_empty() {
        lines.push(rimel::text(format!("{} warnings · {} failed tests", model.warnings.len(), model.tests_failed)).fg(palette::YELLOW));
    }
    crop(rimel::col(lines), 0, width, height)
}

fn cache(model: &Model) -> Vec<Block> {
    let filled = if model.build_finished { BAR_WIDTH } else {
        model.units_total.map_or(BAR_WIDTH, |total| BAR_WIDTH * model.units_done.min(total) / total.max(1))
    };
    let [hits, misses, bypasses] = segments(&model.mix, filled);
    let label = if model.build_finished { "build complete".into() } else {
        model.units_total.map_or("total unknown".into(), |total| format!("{}/{} units", model.units_done, total))
    };
    vec![
        rimel::row([
            rimel::text("Build / cache ").dim(),
            rimel::text("█".repeat(hits)).fg(palette::GREEN),
            rimel::text("█".repeat(misses)).fg(palette::YELLOW),
            rimel::text("█".repeat(bypasses)).fg(palette::SUBTEXT0),
            rimel::text("░".repeat(BAR_WIDTH - filled)).fg(palette::SURFACE1),
            rimel::text(format!("  {label}")),
        ]),
        rimel::row([
            rimel::text(format!("{} hits  ", model.mix.hits)).fg(palette::GREEN),
            rimel::text(format!("{} misses  ", model.mix.misses)).fg(palette::YELLOW),
            rimel::text(format!("{} bypassed", model.mix.bypasses)).fg(palette::SUBTEXT0),
        ]),
        rimel::text(format!("Estimated compiler time saved: {:.2}s", model.mix.saved_ns as f64 / 1e9)).dim(),
    ]
}

pub(super) fn summary(model: &Model) -> Block {
    let (ok, elapsed) = model.finished.unwrap_or((true, model.started.elapsed()));
    let mut lines = vec![
        rimel::text(format!("{} {} in {:.2}s", if ok { "✓" } else { "✗" }, model.command, elapsed.as_secs_f32())).fg(if ok { palette::GREEN } else { palette::RED }).bold(),
        rimel::text(format!("  {} artifacts compiled · {} fresh", model.artifacts, model.fresh)).dim(),
    ];
    if model.testing {
        lines.push(rimel::text(format!("  {} passed · {} failed · {} ignored", model.tests_passed, model.tests_failed, model.tests_ignored)));
    }
    lines.extend(cache(model));
    rimel::col(lines)
}

fn crop(block: Block, scroll: usize, width: u16, height: u16) -> Block {
    // Preserve styles while clipping both axes; browsing can reach every line
    // of a diagnostic even when the terminal is smaller than the upstream view.
    let mut lines: Vec<Vec<Block>> = vec![Vec::new(); usize::from(height)];
    for (x, y, text, style) in block.runs() {
        let y = usize::from(y);
        if y < scroll || y >= scroll + lines.len() || x >= width { continue; }
        let text: String = text.chars().take(usize::from(width - x)).collect();
        lines[y - scroll].push(rimel::text(text).fg(style.fg));
    }
    rimel::col(lines.into_iter().map(rimel::row))
}
